<h1 class="h">Kalendář</h1><div class="sub">Události propojené se zákazníky, zakázkami a uživateli.</div><div class="card"><form class="form" method="post" action="/calendar/save"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><input name="title" placeholder="Název" required><div class="row"><input type="datetime-local" name="start_at" required><input type="datetime-local" name="end_at"></div><div class="row"><select name="customer_id"><option value="">Zákazník</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=View::e($c['company_name']?:$c['last_name'])?></option><?php endforeach;?></select><select name="job_id"><option value="">Zakázka</option><?php foreach($jobs as $j):?><option value="<?=$j['id']?>"><?=View::e($j['name'])?></option><?php endforeach;?></select></div><select name="type"><option>event</option><option>meeting</option><option>task</option><option>job</option></select><textarea name="note" placeholder="Poznámka"></textarea><button class="btn primary">Přidat</button></form></div><div style="height:16px"></div><?php foreach($events as $e):?><div class="card" style="margin-bottom:10px"><b><?=View::e($e['title'])?></b><div class="sub"><?=View::e($e['start_at'])?> · <?=View::e($e['type'])?></div><?=nl2br(View::e($e['note']))?></div><?php endforeach;?>